/// Panel desks and tables (README "Desks and tables"): top, end panels or generic legs,
/// modesty panel, rounded cable slot, rounded front corners and an under-desk drawer pedestal
/// (generated by the ordinary cabinet generator from templates::drawerUnitWithBoxes()).
#include "fos/furniture/templates.hpp"
#include "gen_context.hpp"

#include <cmath>
#include <cstdio>

namespace fos::furniture::detail {
namespace {

core::Error invalid(const Gen& g, const std::string& message) {
    return core::makeError(core::ErrorCode::InvalidArgument, message, g.def.id.str());
}
core::Error violated(const Gen& g, const std::string& message) {
    return core::makeError(core::ErrorCode::ConstraintViolation, message, g.def.id.str());
}
bool finite(double v) { return std::isfinite(v); }
/// Exact decimal text of a millimetre value for a contour expression.
std::string exprNumber(double v) {
    char buf[64];
    std::snprintf(buf, sizeof buf, "%.6f", v);
    return buf;
}

void corner(Gen& g, std::size_t facePart, std::size_t edgePart, JointFastener fastener, const std::string& faceSlot,
            const std::string& edgeSlot) {
    if (fastener == JointFastener::None) return;
    Job j;
    j.kind = JobKind::Corner;
    j.instance = "hw.joint." + edgeSlot + "." + faceSlot;
    j.a = facePart;
    j.b = edgePart;
    j.fastener = fastener;
    g.jobs.push_back(std::move(j));
}

struct Rect {
    double x0, y0, x1, y1;
};
bool overlaps(const Rect& a, const Rect& b) {
    return a.x0 < b.x1 - core::kLengthEps && b.x0 < a.x1 - core::kLengthEps && a.y0 < b.y1 - core::kLengthEps &&
           b.y0 < a.y1 - core::kLengthEps;
}

struct LegData {
    const domain::HardwareDefinition* def = nullptr;
    double plate = 0, spacing = 0, diameter = 0, depth = 0;
};

core::Result<LegData> legData(const Gen& g, const DeskSpec& d, const std::string& who) {
    LegData out;
    out.def = g.libs.findHardware(d.leg);
    if (!out.def)
        return core::makeError(core::ErrorCode::NotFound,
                               who + " uses the leg '" + d.leg.str() +
                                   "', which is not in the hardware library. Add it (furniture::genericLegDefinition() "
                                   "provides the generic one) or select another leg.",
                               g.def.id.str());
    const std::pair<const char*, double*> keys[] = {{leg_keys::kPlateSize, &out.plate},
                                                     {leg_keys::kPlateHoleSpacing, &out.spacing},
                                                     {leg_keys::kPlateHoleDiameter, &out.diameter},
                                                     {leg_keys::kPlateHoleDepth, &out.depth}};
    for (const auto& [key, dst] : keys) {
        const auto it = out.def->params.find(key);
        if (it == out.def->params.end() || !finite(it->second) || it->second <= 0)
            return invalid(g, who + ": the leg '" + out.def->name + "' needs a positive parameter '" + key + "'.");
        *dst = it->second;
    }
    if (out.spacing + out.diameter > out.plate + core::kLengthEps)
        return invalid(g, who + ": the plate holes of leg '" + out.def->name + "' (" + num(out.spacing) + " mm apart, " +
                              num(out.diameter) + " mm) do not fit on its " + num(out.plate) + " mm plate.");
    return out;
}

/// Checks of the spec values that do not depend on the leg / pedestal hardware.
core::Result<void> checkSpec(const Gen& g, const DeskSpec& d, const std::string& who, double W, double H, double D,
                             double T) {
    const struct {
        const char* name;
        double value, lo, hi;
    } sizes[] = {{"width", W, kDeskMinWidth, kDeskMaxWidth},
                 {"depth", D, kDeskMinDepth, kDeskMaxDepth},
                 {"height", H, kDeskMinHeight, kDeskMaxHeight}};
    for (const auto& s : sizes)
        if (!finite(s.value) || s.value < s.lo - core::kLengthEps || s.value > s.hi + core::kLengthEps)
            return violated(g, who + " has a " + s.name + " of " + num(s.value) + " mm; desks and tables must be " +
                                   num(s.lo) + " .. " + num(s.hi) + " mm.");
    const double r = d.frontCornerRadius;
    if (!finite(r) || r < 0 || r >= std::min(W, D) / 2)
        return invalid(g, who + ": the front corner radius is " + num(r) + " mm; it must be at least 0 and less than " +
                              num(std::min(W, D) / 2) + " mm (half the smaller top dimension).");
    if (d.support == DeskSupport::Legs) {
        if (d.modestyPanel)
            return invalid(g, who + " stands on legs but asks for a modesty panel; a modesty panel is fixed to end "
                                    "panels. Switch the modesty panel off or use end panels.");
        if (d.pedestal)
            return invalid(g, who + " stands on legs but has a drawer pedestal; the pedestal is supported only between "
                                    "end panels. Remove the pedestal or use end panels.");
    }
    if (d.support == DeskSupport::Panels && d.modestyPanel) {
        if (!finite(d.modestyHeight) || d.modestyHeight <= 0 || d.modestyHeight > H - T + core::kLengthEps)
            return invalid(g, who + ": the modesty panel height is " + num(d.modestyHeight) +
                                  " mm; it must be greater than 0 and at most the clear height under the top (" +
                                  num(H - T) + " mm).");
        if (!finite(d.modestySetback) || d.modestySetback < 0 || d.modestySetback + T > D + core::kLengthEps)
            return invalid(g, who + ": the modesty panel setback is " + num(d.modestySetback) +
                                  " mm; it must be at least 0 and leave room for the " + num(T) + " mm panel within the depth " +
                                  num(D) + " mm.");
    }
    if (d.pedestal) {
        const DeskPedestal& p = *d.pedestal;
        if (p.drawers < 1 || p.drawers > kDeskMaxPedestalDrawers)
            return invalid(g, who + ": the drawer pedestal has " + std::to_string(p.drawers) + " drawers; allowed are 1 .. " +
                                  std::to_string(kDeskMaxPedestalDrawers) + ".");
        if (!finite(p.width) || p.width < kDeskMinPedestalWidth || p.width > W - 2 * T + core::kLengthEps)
            return violated(g, who + ": the drawer pedestal is " + num(p.width) + " mm wide; it must be " +
                                   num(kDeskMinPedestalWidth) + " .. " + num(W - 2 * T) +
                                   " mm (clear width between the end panels).");
    }
    if (d.cableCutout) {
        const DeskCableCutout& c = *d.cableCutout;
        if (!finite(c.width) || c.width <= 0 || !finite(c.length) || c.length <= c.width)
            return invalid(g, who + ": the cable slot is " + num(c.length) + " x " + num(c.width) +
                                  " mm; its width must be greater than 0 and its length greater than its width.");
        if (!finite(c.rearDistance) || c.rearDistance <= 0 || c.rearDistance + c.width >= D - core::kLengthEps)
            return invalid(g, who + ": a cable slot " + num(c.width) + " mm wide at " + num(c.rearDistance) +
                                  " mm from the rear edge does not fit into the top depth of " + num(D) + " mm.");
        if (!finite(c.centerOffset))
            return invalid(g, who + ": the cable slot centre offset must be a finite number.");
    }
    if (d.support == DeskSupport::Legs && (!finite(d.legInset) || d.legInset <= 0))
        return invalid(g, who + ": the leg inset is " + num(d.legInset) + " mm; it must be greater than 0.");
    return {};
}

/// Drawer pedestal: an ordinary drawer unit generated on its own and merged into the desk.
core::Result<void> buildPedestal(Gen& g, const DeskPedestal& p, double x0, double height, double depth) {
    templates::TemplateMaterials m;
    const MaterialAssignment& ma = g.def.materials;
    m.carcass = ma.carcass;
    m.back = ma.back;
    m.front = ma.front;
    m.visibleEdge = ma.visibleEdge;
    m.hiddenEdge = ma.hiddenEdge;
    const std::string subId = g.def.id.str() + "/pedestal";
    CabinetDefinition sub = templates::drawerUnitWithBoxes(domain::AssemblyId(subId), m);
    sub.name = "Drawer pedestal";
    sub.materials.drawer = ma.drawer;
    sub.materials.drawerBottom = ma.drawerBottom;
    sub.materials.frontEdge = ma.frontEdge;
    sub.hardware = g.def.hardware;
    sub.hardware.hanger = {};
    sub.interior.front->drawerHeights.assign(static_cast<std::size_t>(p.drawers), SectionSize::weight(1));
    parametric::Transaction tx;
    tx.setValue(param::kWidth, p.width).setValue(param::kHeight, height).setValue(param::kDepth, depth);
    const std::string who = "The drawer pedestal of desk '" + g.def.id.str() + "'";
    if (auto r = sub.parameters.apply(tx); !r) return violated(g, who + ": " + r.error().message);
    auto made = generate(sub, g.libs);
    if (!made) return core::makeError(made.error().code, who + ": " + made.error().message, g.def.id.str());
    GenerationResult& res = made.value();
    const Transform shift = Transform::translation({x0, 0, 0});
    for (domain::Part& part : res.assembly.parts) {
        part.placement = shift * part.placement;
        const auto slot = part.custom.find("furniture.slot");
        if (slot != part.custom.end()) slot->second = "pedestal/" + slot->second;
        g.assembly.parts.push_back(std::move(part));
    }
    for (domain::HardwareInstance& h : res.assembly.hardware) {
        h.position = shift.applyPoint(h.position);
        g.assembly.hardware.push_back(std::move(h));
    }
    // generate() already validated the pedestal's machining; keep only its own findings.
    for (auto& d : res.diagnostics)
        if (d.code.rfind("machining.", 0) != 0) g.diagnostics.push_back(std::move(d));
    return {};
}

void drillLegs(Gen& g, std::size_t top, const LegData& leg, const DeskSpec& d, double W, double D, double zUnder) {
    domain::Part& part = g.assembly.parts[top];
    domain::Face under = domain::Face::A;
    for (const domain::Face f : {domain::Face::A, domain::Face::B})
        if (machining::faceFrameInAssembly(part, f).toolDir.z > 0.5) under = f;
    const struct {
        const char* name;
        double x, y;
    } legs[] = {{"front_left", d.legInset, d.legInset},
                {"front_right", W - d.legInset, d.legInset},
                {"rear_left", d.legInset, D - d.legInset},
                {"rear_right", W - d.legInset, D - d.legInset}};
    const double h = leg.spacing / 2;
    for (const auto& l : legs) {
        const std::string instance = g.partId(std::string("hw.leg.") + l.name);
        domain::HardwareInstance inst;
        inst.id = domain::HardwareInstanceId(instance);
        inst.definition = leg.def->id;
        inst.parts = {part.id};
        inst.position = {l.x, l.y, zUnder};
        inst.note = "Leg " + num(zUnder) + " mm long under the top (mounting plate screwed to the underside)";
        g.assembly.hardware.push_back(std::move(inst));
        int k = 0;
        for (const double dy : {-h, h})
            for (const double dx : {-h, h}) {
                const machining::FaceCoord c = machining::assemblyToFace(part, under, {l.x + dx, l.y + dy, zUnder});
                domain::Hole hole;
                hole.face = under;
                hole.u = c.u;
                hole.v = c.v;
                hole.diameter = leg.diameter;
                hole.depth = leg.depth;
                domain::Operation op;
                op.id = domain::OperationId(part.id.str() + "/op.leg." + l.name + "." + std::to_string(++k));
                op.shape = hole;
                op.source = instance;
                op.note = "Leg mounting plate pilot hole";
                part.operations.push_back(std::move(op));
            }
    }
}

} // namespace

core::Result<void> buildDesk(Gen& g) {
    namespace p = param;
    const DeskSpec& d = *g.def.desk;
    const std::string who = "Desk '" + g.def.id.str() + "'";
    const Section& root = g.def.interior;
    if (g.def.corner.kind != CornerKind::None)
        return invalid(g, who + " cannot also be a corner cabinet; set the corner kind to None.");
    if (root.split != SplitDirection::None || root.shelfCount != 0 || root.front)
        return invalid(g, who + " has an interior layout (split, shelves or a front); a desk has none. Remove them "
                                "(use the drawer pedestal for drawers).");
    const double T = g.v(p::kThickness), W = g.v(p::kWidth), H = g.v(p::kHeight), D = g.v(p::kDepth);
    if (auto r = checkSpec(g, d, who, W, H, D, T); !r) return r;
    const bool panels = d.support == DeskSupport::Panels;
    const double zUnder = H - T; // underside of the top = clear height
    const ConstructionOptions& o = g.def.construction;

    LegData leg;
    if (!panels) {
        auto l = legData(g, d, who);
        if (!l) return l.error();
        leg = l.value();
        if (leg.depth >= T - core::kLengthEps)
            return violated(g, who + ": the leg plate holes are " + num(leg.depth) + " mm deep but the top is only " +
                                   num(T) + " mm thick.");
        const double a = d.legInset - leg.plate / 2; // plate edge to the top edges
        if (a < -core::kLengthEps || 2 * d.legInset >= std::min(W, D))
            return violated(g, who + ": legs with a " + num(leg.plate) + " mm plate at " + num(d.legInset) +
                                   " mm from the edges do not fit under a " + num(W) + " x " + num(D) + " mm top.");
        const double r = d.frontCornerRadius;
        if (a < r && (r - a) * std::sqrt(2.0) > r + core::kLengthEps)
            return violated(g, who + ": the front corner radius of " + num(r) + " mm cuts into the leg plates (plate edge " +
                                   num(a) + " mm from the edges); reduce the radius or increase the leg inset.");
        const auto lo = leg.def->params.find(leg_keys::kHeightMin), hi = leg.def->params.find(leg_keys::kHeightMax);
        if ((lo != leg.def->params.end() && zUnder < lo->second - core::kLengthEps) ||
            (hi != leg.def->params.end() && zUnder > hi->second + core::kLengthEps))
            g.warn("furniture.desk.leg_height",
                   who + " needs legs " + num(zUnder) + " mm long, outside the length range of '" + leg.def->name + "' (" +
                       (lo != leg.def->params.end() ? num(lo->second) : std::string("-")) + " .. " +
                       (hi != leg.def->params.end() ? num(hi->second) : std::string("-")) + " mm).",
                   g.def.id.str());
    }

    // Knee clearance rule of thumb (warnings only).
    const double clearWidth = panels ? W - 2 * T - (d.pedestal ? d.pedestal->width : 0.0) : W - 2 * d.legInset - leg.plate;
    if (zUnder < kDeskKneeClearance - core::kLengthEps)
        g.warn("furniture.desk.knee_clearance",
               who + " leaves " + num(zUnder) + " mm clear height under the top; the rule of thumb for seated work is at "
                     "least " + num(kDeskKneeClearance) + " mm.",
               g.def.id.str());
    if (clearWidth < kDeskKneeClearance - core::kLengthEps)
        g.warn("furniture.desk.knee_clearance",
               who + " leaves " + num(clearWidth) + " mm clear width for the knees between its supports; the rule of thumb "
                     "is at least " + num(kDeskKneeClearance) + " mm.",
               g.def.id.str());

    // Top: length -> +X, width -> +Y (L1 = front edge), thickness -> +Z.
    using domain::PartRole;
    const Edges all{EdgeUse::Visible, EdgeUse::Visible, EdgeUse::Visible, EdgeUse::Visible};
    const std::size_t top = g.addPart("top", "Desk top", PartRole::Top, MaterialRole::Carcass, W, D, T,
                                      Transform::translation({0, 0, zUnder}), all);
    if (d.frontCornerRadius > 0) {
        if (const auto ov = g.def.materials.overrides.find("top");
            ov != g.def.materials.overrides.end() && ov->second.contour)
            g.warn("furniture.desk.corner_radius_overridden",
                   who + ": the contour override of the top replaces the front corner radius of " +
                       num(d.frontCornerRadius) + " mm.",
                   g.def.id.str());
        ContourSpec c;
        c.kind = ContourKind::RoundedCorners;
        c.radii[0] = c.radii[1] = exprNumber(d.frontCornerRadius);
        g.generatedContours["top"] = c;
    }

    if (panels) {
        // End panels: like carcass sides (length up, width to the back, thickness -X).
        const Edges endEdges{EdgeUse::Visible, EdgeUse::Visible, EdgeUse::Raw, EdgeUse::Raw};
        const std::size_t left = g.addPart("end.left", "Left end panel", PartRole::Side, MaterialRole::Carcass, zUnder,
                                           D, T, Transform::fromAxes(kUp, kBack, {T, 0, 0}), endEdges);
        const std::size_t right = g.addPart("end.right", "Right end panel", PartRole::Side, MaterialRole::Carcass,
                                            zUnder, D, T, Transform::fromAxes(kUp, kBack, {W, 0, 0}), endEdges);
        corner(g, top, left, o.topFastener, "top", "end.left");
        corner(g, top, right, o.topFastener, "top", "end.right");
        if (d.modestyPanel) {
            // Length -> +X, width -> +Z (L1 = lower edge), thickness -> -Y; rear face at depth - setback.
            const std::size_t modesty =
                g.addPart("modesty", "Modesty panel", PartRole::Back, MaterialRole::Carcass, W - 2 * T, d.modestyHeight,
                          T, Transform::fromAxes(kRight, kUp, {T, D - d.modestySetback, zUnder - d.modestyHeight}),
                          Edges{EdgeUse::Visible, EdgeUse::Raw, EdgeUse::Raw, EdgeUse::Raw});
            corner(g, left, modesty, o.dividerFastener, "end.left", "modesty");
            corner(g, right, modesty, o.dividerFastener, "end.right", "modesty");
        }
    } else {
        drillLegs(g, top, leg, d, W, D, zUnder);
    }

    if (d.cableCutout) {
        const DeskCableCutout& c = *d.cableCutout;
        const double cx = W / 2 + c.centerOffset;
        const Rect slot{cx - c.length / 2, D - c.rearDistance - c.width, cx + c.length / 2, D - c.rearDistance};
        const double margin = panels ? T : 0.0;
        if (slot.x0 < margin + core::kLengthEps || slot.x1 > W - margin - core::kLengthEps)
            return violated(g, who + ": the cable slot spans x " + num(slot.x0) + " .. " + num(slot.x1) +
                                   " mm and must stay within x " + num(margin) + " .. " + num(W - margin) +
                                   " mm (clear of the end panels).");
        if (!panels)
            for (const double lx : {d.legInset, W - d.legInset})
                for (const double ly : {d.legInset, D - d.legInset}) {
                    const Rect plate{lx - leg.plate / 2, ly - leg.plate / 2, lx + leg.plate / 2, ly + leg.plate / 2};
                    if (overlaps(slot, plate))
                        return violated(g, who + ": the cable slot overlaps the leg plate at (" + num(lx) + ", " + num(ly) +
                                               "); move or shorten the slot.");
                }
        PendingCutout pc;
        pc.slot = "top";
        pc.lo = {slot.x0, slot.y0, zUnder};
        pc.hi = {slot.x1, slot.y1, H};
        pc.radius = c.width / 2;
        pc.owner = "cable slot of desk '" + g.def.id.str() + "'";
        g.cutouts.push_back(std::move(pc));
    }

    if (d.pedestal) {
        const DeskPedestal& ped = *d.pedestal;
        const double x0 = ped.side == DeskPedestalSide::Left ? T : W - T - ped.width;
        const double depth = d.modestyPanel ? D - d.modestySetback - T : D;
        if (auto r = buildPedestal(g, ped, x0, zUnder, depth); !r) return r;
    }
    return {};
}

} // namespace fos::furniture::detail
